const raw = $input.first().json;
const e = raw && raw.body ? raw.body : raw;
function toArr(v){ if (Array.isArray(v)) return v; if (typeof v === 'string' && v.trim()) return v.split(/[\n,]+/).map(function(s){ return s.trim(); }).filter(Boolean); return []; }
const req = ['event_id','event_name','event_description','event_date','city','country','event_topic','event_capacity','registration_url','event_status'];
const missing = req.filter(function(k){ return e[k] === undefined || e[k] === null || e[k] === ''; });
const facts = toArr(e.approved_facts);
if (!facts.length) { missing.push('approved_facts'); }
const out = Object.assign({}, e, {
  target_industries: toArr(e.target_industries),
  target_functions: toArr(e.target_functions),
  target_career_stages: toArr(e.target_career_stages),
  target_cities: toArr(e.target_cities),
  approved_speakers: toArr(e.approved_speakers),
  approved_facts: facts,
  batch_from: Number(e.batch_from) || 0,
  batch_to: Number(e.batch_to) || 0,
  max_invitations: Number(e.max_invitations) || 10,
  event_capacity: Number(e.event_capacity) || 0,
  communications_approved: e.communications_approved === true || String(e.communications_approved).toLowerCase() === 'true',
  city: e.city || '',
  event_date: e.event_date || '',
  validation_status: missing.length ? 'FAILED' : 'PASSED',
  missing_fields: missing,
  run_id: $execution.id,
  received_at: new Date().toISOString()
});
return [{ json: out }];

const ev = $('Validate Event Payload').first().json;
const rows = $input.all().map(function(i){ return i.json; }).filter(function(r){ return r && r.event_id === ev.event_id && String(r.status || '').toUpperCase() === 'REGISTERED'; });
const registered_count = rows.length;
const capacity = Number(ev.event_capacity) || 0;
const remaining_capacity = Math.max(capacity - registered_count, 0);
const capacity_reached = capacity > 0 && registered_count >= capacity;
let campaign_gate = 'PROCEED';
let stop_reason = '';
if (String(ev.event_status || '').toUpperCase() !== 'OPEN') { campaign_gate = 'STOP'; stop_reason = 'EVENT_CLOSED'; }
else if (ev.communications_approved !== true) { campaign_gate = 'STOP'; stop_reason = 'COMMUNICATIONS_NOT_APPROVED'; }
else if (capacity_reached) { campaign_gate = 'STOP'; stop_reason = 'CAPACITY_REACHED'; }
const invite_budget = Math.max(Math.min(Number(ev.max_invitations) || 0, remaining_capacity), 0);
return [{ json: Object.assign({}, ev, { registered_count: registered_count, remaining_capacity: remaining_capacity, capacity_reached: capacity_reached, invite_budget: invite_budget, campaign_gate: campaign_gate, stop_reason: stop_reason }) }];

