const ev = $('Compute Capacity Status').first().json;
const now = Date.now();
function lc(v){ return String(v == null ? '' : v).toLowerCase().trim(); }
function truthy(v){ return v === true || ['true','yes','y','1'].indexOf(String(v).trim().toLowerCase()) >= 0; }
const targetCities = (ev.target_cities || []).map(lc);
const bFrom = Number(ev.batch_from) || 0;
const bTo = Number(ev.batch_to) || 0;
const out = [];
$input.all().forEach(function(item){
  const a = item.json;
  if (!a || !a.alumni_id) { return; }
  let status = 'ELIGIBLE';
  let reason = '';
  const pref = lc(a.communication_preference);
  const d = a.last_email_sent_at ? new Date(a.last_email_sent_at) : null;
  const days = (d && !isNaN(d.getTime())) ? Math.floor((now - d.getTime()) / 86400000) : 9999;
  const prefAllowsEmail = !pref || pref.indexOf('email') >= 0 || pref === 'any' || pref === 'all';
  const year = Number(a.graduation_year) || 0;
  if (!truthy(a.email_consent)) { status = 'EXCLUDED'; reason = 'NO_CONSENT'; }
  else if (truthy(a.unsubscribed)) { status = 'EXCLUDED'; reason = 'UNSUBSCRIBED'; }
  else if (!prefAllowsEmail) { status = 'EXCLUDED'; reason = 'COMMUNICATION_PREFERENCE'; }
  else if (days < 21) { status = 'EXCLUDED'; reason = 'RECENTLY_CONTACTED'; }
  else if (targetCities.length && targetCities.indexOf(lc(a.city)) < 0) { status = 'EXCLUDED'; reason = 'CITY_NOT_TARGETED'; }
  else if (bFrom && year && year < bFrom) { status = 'EXCLUDED'; reason = 'BATCH_NOT_TARGETED'; }
  else if (bTo && year && year > bTo) { status = 'EXCLUDED'; reason = 'BATCH_NOT_TARGETED'; }
  if (status !== 'ELIGIBLE') { return; }
  out.push({ json: Object.assign({}, a, {
    event_id: ev.event_id,
    eligibility_status: status,
    exclusion_reason: reason,
    days_since_last_email: days,
    decided_by: 'DETERMINISTIC_RULES'
  }) });
});
return out;

const ev = $('Compute Capacity Status').first().json;
function lc(v){ return String(v == null ? '' : v).toLowerCase().trim(); }
function toList(v){ if (Array.isArray(v)) return v.map(lc).filter(Boolean); return lc(v).split(/[;,|]/).map(function(s){ return s.trim(); }).filter(Boolean); }
function words(s){ return lc(s).split(/[^a-z0-9]+/).filter(function(w){ return w.length > 3; }); }
function related(a, b){ const wa = words(a); const wb = words(b); return wa.some(function(w){ return wb.indexOf(w) >= 0; }); }
function near(v, list){ const x = lc(v); if (!x) return false; return list.some(function(t){ return t.indexOf(x) >= 0 || x.indexOf(t) >= 0 || related(t, x); }); }
function stageIdx(s){ const x = lc(s); if (!x) return -1; if (x.indexOf('early') >= 0 || x.indexOf('junior') >= 0 || x.indexOf('analyst') >= 0 || x.indexOf('associate') >= 0) return 0; if (x.indexOf('mid') >= 0 || x.indexOf('manager') >= 0) return 1; if (x.indexOf('senior') >= 0 || x.indexOf('director') >= 0 || x.indexOf('principal') >= 0) return 2; if (x.indexOf('lead') >= 0 || x.indexOf('chief') >= 0 || x.indexOf('head') >= 0 || x.indexOf('partner') >= 0 || x.indexOf('founder') >= 0) return 3; return -1; }
const tInd = toList(ev.target_industries);
const tFn = toList(ev.target_functions);
const tStageIdx = toList(ev.target_career_stages).map(stageIdx).filter(function(i){ return i >= 0; });
const topic = lc(ev.event_topic);
const scored = [];
$input.all().forEach(function(item){
  const a = item.json;
  const matched = [];
  const unmatched = [];
  const gaps = [];
  let industry = 0;
  const ind = lc(a.industry);
  if (!ind) { gaps.push('industry'); unmatched.push('Industry missing from profile'); }
  else if (tInd.indexOf(ind) >= 0) { industry = 25; matched.push('Target industry match: ' + a.industry); }
  else if (near(ind, tInd)) { industry = 12; matched.push('Adjacent industry: ' + a.industry); }
  else { unmatched.push('Industry outside target list: ' + a.industry); }
  let interest = 0;
  const ints = toList(a.interests);
  const pastTopics = toList(a.past_event_topics);
  if (!ints.length) { gaps.push('interests'); unmatched.push('No stated interests on file'); }
  else if (ints.indexOf(topic) >= 0) { interest = 20; matched.push('Stated interest in ' + ev.event_topic); }
  else if (near(topic, ints) || near(topic, pastTopics)) { interest = 10; matched.push('Related interest or past topic overlap'); }
  else { unmatched.push('No interest overlap with ' + ev.event_topic); }
  let location = 0;
  const city = lc(a.city);
  if (!city) { gaps.push('city'); unmatched.push('City missing from profile'); }
  else if (city === lc(ev.city)) { location = 20; matched.push('Same city as venue: ' + a.city); }
  else if (lc(a.country) === lc(ev.country)) { location = 8; matched.push('Same country, different city (' + a.city + ') - travel required'); }
  else { unmatched.push('Different country (' + (a.country || 'unknown') + ') - significant travel'); }
  let stage = 0;
  const si = stageIdx(a.seniority);
  if (si < 0) { gaps.push('seniority'); unmatched.push('Career stage unknown'); }
  else if (tStageIdx.indexOf(si) >= 0) { stage = 15; matched.push('Target career stage: ' + a.seniority); }
  else if (tStageIdx.some(function(t){ return Math.abs(t - si) === 1; })) { stage = 8; matched.push('Adjacent career stage: ' + a.seniority); }
  else { unmatched.push('Career stage outside target: ' + a.seniority); }
  let engagement = 0;
  const pc = Number(a.past_event_count) || 0;
  if (pc >= 3) { engagement = 10; matched.push('Attended ' + pc + ' previous alumni events'); }
  else if (pc >= 1) { engagement = 5; matched.push('Attended ' + pc + ' previous alumni event(s)'); }
  else { unmatched.push('No prior event attendance recorded'); }
  let func = 0;
  const fn = lc(a['function']);
  if (!fn) { gaps.push('function'); unmatched.push('Function missing from profile'); }
  else if (tFn.indexOf(fn) >= 0) { func = 10; matched.push('Target function match: ' + a['function']); }
  else if (near(fn, tFn)) { func = 5; matched.push('Related function: ' + a['function']); }
  else { unmatched.push('Function outside target: ' + a['function']); }
  const score = industry + interest + location + stage + engagement + func;
  const band = score >= 80 ? 'HIGH' : (score >= 60 ? 'MEDIUM' : (score >= 40 ? 'LOW' : 'SUPPRESS'));
  const travel = (city && city === lc(ev.city)) ? 'LOCAL' : (lc(a.country) === lc(ev.country) ? 'DOMESTIC_TRAVEL' : 'INTERNATIONAL_TRAVEL');
  scored.push(Object.assign({}, a, {
    relevance_score: score,
    relevance_band: band,
    score_breakdown: { industry_match: industry, interest_topic_match: interest, location_match: location, career_stage: stage, past_engagement: engagement, function_match: func },
    matched_signals: matched,
    unmatched_signals: unmatched,
    profile_gaps: gaps,
    travel_situation: travel,
    scoring_model: 'relevance-v1.0 (25/20/20/15/10/10)',
    scored_by: 'DETERMINISTIC_ENGINE'
  }));
});
const qualified = scored.filter(function(a){ return a.relevance_score >= 60; })
  .sort(function(x, y){ return y.relevance_score - x.relevance_score; });

if (!qualified.length) {
  const bestScore = scored.length ? Math.max.apply(null, scored.map(function(a){ return a.relevance_score; })) : 0;
  const topCandidates = scored.slice().sort(function(x, y){ return y.relevance_score - x.relevance_score; }).slice(0, 5)
    .map(function(a){ return (a.first_name || a.alumni_id) + ' (' + a.alumni_id + ') - score ' + a.relevance_score + '/100, ' + a.relevance_band; });
  return [{ json: {
    no_candidates: true,
    event_id: ev.event_id,
    event_name: ev.event_name,
    event_city: ev.city,
    eligible_count: scored.length,
    best_score: bestScore,
    threshold: 60,
    top_candidates: topCandidates.length ? topCandidates : ['No alumni passed the hard eligibility rules at all.']
  } }];
}

const budget = Number(ev.invite_budget) || 0;
return qualified.map(function(a, idx){
  const queueStatus = idx < budget ? 'INVITED' : 'WAITLIST';
  return { json: Object.assign({}, a, {
    no_candidates: false,
    queue_status: queueStatus,
    queue_id: ev.event_id + '-' + a.alumni_id,
    ai_input: {
      alumni: { alumni_id: a.alumni_id, first_name: a.first_name || '', city: a.city || '', country: a.country || '', graduation_year: a.graduation_year || '', industry: a.industry || '', job_function: a['function'] || '', seniority: a.seniority || '', interests: a.interests || '', past_event_count: Number(a.past_event_count) || 0, past_event_topics: a.past_event_topics || '', chapter: a.chapter || '', profile_gaps: a.profile_gaps },
      event: { event_id: ev.event_id, event_name: ev.event_name, event_description: ev.event_description, event_date: ev.event_date, event_time: ev.event_time || '', city: ev.city, venue: ev.venue || '', country: ev.country, event_topic: ev.event_topic, event_fee: ev.event_fee || '', registration_url: ev.registration_url, approved_facts: ev.approved_facts, approved_speakers: ev.approved_speakers },
      deterministic_scoring: { relevance_score: a.relevance_score, relevance_band: a.relevance_band, score_breakdown: a.score_breakdown, matched_signals: a.matched_signals, unmatched_signals: a.unmatched_signals, travel_situation: a.travel_situation }
    }
  }) };
});

