Return ONLY the required JSON object. Echo alumni_id and event_id exactly as supplied.

parameters.jsCode:
const pool = {};
$('Ready for AI Personalization').all().forEach(function(i){ pool[i.json.alumni_id] = i.json; });
const out = [];
$input.all().forEach(function(item){
  const ai = (item.json && item.json.output) ? item.json.output : item.json;
  const base = pool[ai.alumni_id];
  const flags = Array.isArray(ai.risk_flags) ? ai.risk_flags.slice() : [];
  let conf = Number(ai.personalization_confidence);
  if (isNaN(conf)) { conf = 0; }
  if (!base) { flags.push('AI_BINDING_ERROR'); conf = 0; }
  const claims = Array.isArray(ai.claims_used) ? ai.claims_used : [];
  const approved = (base && base.ai_input) ? base.ai_input.event.approved_facts : [];
  const unapproved = claims.filter(function(c){ return approved.indexOf(c) < 0; });
  if (unapproved.length) { flags.push('CLAIM_NOT_IN_APPROVED_FACTS'); }
  out.push({ json: Object.assign({}, base || {}, {
    ai_returned_alumni_id: ai.alumni_id || '',
    relevance_reason: ai.relevance_reason || '',
    personalization_angle: ai.personalization_angle || '',
    personalization_confidence: conf,
    travel_context: ai.travel_context || '',
    recommended_tone: ai.recommended_tone || '',
    email_subject: ai.email_subject || '',
    email_body: ai.email_body || '',
    claims_used: claims,
    unapproved_claims: unapproved,
    risk_flags: flags,
    requires_human_review: true,
    ai_status: 'OK',
    personalization_source: 'AI_AGENT'
  }) });
});
return out;

const out = [];
$input.all().forEach(function(item){
  const a = item.json;
  const ev = (a.ai_input && a.ai_input.event) ? a.ai_input.event : {};
  const facts = Array.isArray(ev.approved_facts) ? ev.approved_facts : [];
  const subject = 'Invitation: ' + ev.event_name + ' - ' + ev.city;
  const body = 'Dear ' + (a.first_name || 'Alumnus') + ',\n\nThe Alumni Office is hosting ' + ev.event_name + ' in ' + ev.city + ' on ' + ev.event_date + '.\n\n' + facts.join('\n') + '\n\nRegistration: ' + ev.registration_url + '\n\nIf you would prefer not to receive event invitations, you can opt out using the link at the end of this email.\n\nAlumni Relations Office';
  out.push({ json: Object.assign({}, a, {
    relevance_reason: 'AI personalization unavailable - deterministic score retained',
    personalization_angle: 'Conservative event-focused invitation (no personalization)',
    personalization_confidence: 0,
    travel_context: a.travel_situation || '',
    recommended_tone: 'Neutral, factual',
    email_subject: subject,
    email_body: body,
    claims_used: facts,
    unapproved_claims: [],
    risk_flags: ['AI_PERSONALIZATION_FAILURE'],
    requires_human_review: true,
    ai_status: 'AI_FAILURE',
    personalization_source: 'FALLBACK_TEMPLATE'
  }) });
});
return out;

function esc(s){ return String(s == null ? '' : s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;'); }
const out = [];
$input.all().forEach(function(item){
  const a = item.json;
  const band = a.relevance_band === 'HIGH' ? 'HIGH' : 'MEDIUM';
  const bandBg = band === 'HIGH' ? '#fff1f0' : '#eef2ff';
  const bandColor = band === 'HIGH' ? '#b91c1c' : '#3730a3';
  const gradStart = band === 'HIGH' ? '#f59e0b' : '#6366f1';
  const gradEnd = band === 'HIGH' ? '#ef4444' : '#06b6d4';
  const initials = (a.first_name || a.alumni_id || 'AL').trim().slice(0, 2).toUpperCase();
  const confPct = Math.round((Number(a.personalization_confidence) || 0) * 100);
  const copyModeLabel = a.copy_mode === 'PERSONALIZED' ? 'AI Personalized' : 'Approved Template';
  const pills = (a.matched_signals || []).slice(0, 6).map(function(s){
    return '<span style="display:inline-block;background:#ecfdf5;color:#065f46;font-size:12px;border-radius:999px;padding:5px 12px;margin:0 6px 6px 0;">' + esc(s) + '</span>';
  }).join('');
  const html = '<div style="font-family:\'Segoe UI\',Arial,sans-serif;max-width:640px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;border:1px solid #e5e7eb;">' +
    '<div style="background:linear-gradient(135deg,' + gradStart + ',' + gradEnd + ');padding:32px 28px;text-align:center;">' +
      '<div style="width:52px;height:52px;border-radius:50%;background:rgba(255,255,255,0.25);color:#fff;font-weight:700;font-size:18px;line-height:52px;margin:0 auto 12px;">' + esc(initials) + '</div>' +
      '<div style="color:#fde9d9;font-size:11px;letter-spacing:1.5px;text-transform:uppercase;opacity:0.95;">AlumniMatch &middot; Approval Required</div>' +
      '<div style="color:#fff;font-size:20px;font-weight:700;margin-top:4px;">' + esc(a.first_name) + ' (' + esc(a.alumni_id) + ')</div>' +
      '<div style="color:#fff;font-size:15px;margin-top:2px;opacity:0.95;">' + esc(a.event_name) + '</div>' +
    '</div>' +
    '<div style="padding:24px 26px;">' +
      '<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:12px 16px;font-size:13px;color:#92400e;margin-bottom:20px;"><b>Reviewer note:</b> ' + esc(a.review_reason) + '</div>' +
      '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>' +
        '<td width="33%" style="padding-right:8px;"><div style="background:' + bandBg + ';border-radius:10px;padding:14px;text-align:center;">' +
          '<div style="font-size:20px;font-weight:800;color:' + bandColor + ';">' + esc(a.relevance_score) + '/100</div>' +
          '<div style="font-size:10px;text-transform:uppercase;color:' + bandColor + ';letter-spacing:0.5px;">' + esc(band) + '</div>' +
        '</div></td>' +
        '<td width="33%" style="padding:0 4px;"><div style="background:#eef2ff;border-radius:10px;padding:14px;text-align:center;">' +
          '<div style="font-size:20px;font-weight:800;color:#4338ca;">' + confPct + '%</div>' +
          '<div style="font-size:10px;text-transform:uppercase;color:#4338ca;letter-spacing:0.5px;">CONFIDENCE</div>' +
        '</div></td>' +
        '<td width="33%" style="padding-left:8px;"><div style="background:#f1f5f9;border-radius:10px;padding:14px;text-align:center;">' +
          '<div style="font-size:13px;font-weight:700;color:#334155;">' + esc(copyModeLabel) + '</div>' +
          '<div style="font-size:10px;text-transform:uppercase;color:#64748b;letter-spacing:0.5px;">COPY MODE</div>' +
        '</div></td>' +
      '</tr></table>' +
      '<div style="margin-top:20px;"><div style="font-size:12px;font-weight:700;color:#374151;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.5px;">Who</div>' +
        '<div style="font-size:14px;color:#111827;">' + esc(a.city) + ', ' + esc(a.country) + ' &middot; ' + esc(a.travel_situation) + '</div>' +
        '<div style="font-size:14px;color:#111827;">' + esc(a.industry) + ' / ' + esc(a['function']) + ' / ' + esc(a.seniority) + ' &middot; Batch ' + esc(a.graduation_year) + '</div>' +
      '</div>' +
      '<div style="margin-top:16px;"><div style="font-size:12px;font-weight:700;color:#374151;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.5px;">Matched signals</div>' + (pills || '<span style="font-size:13px;color:#9ca3af;">None</span>') + '</div>' +
      '<div style="margin-top:16px;"><div style="font-size:12px;font-weight:700;color:#374151;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.5px;">AI reasoning</div>' +
        '<div style="font-size:14px;color:#374151;line-height:1.5;">' + esc(a.relevance_reason) + '</div>' +
        '<div style="font-size:13px;color:#6b7280;margin-top:4px;">Angle: ' + esc(a.personalization_angle) + '</div>' +
        '<div style="font-size:13px;color:#6b7280;">Facts used: ' + esc((a.claims_used || []).join('; ')) + '</div>' +
      '</div>' +
      '<div style="margin-top:18px;font-size:12px;color:#9ca3af;font-style:italic;">Click Review &amp; Respond below to see the exact subject and body, edit if needed, and record your decision.</div>' +
    '</div>' +
  '</div>';
  out.push({ json: Object.assign({}, a, { approval_html: html }) });
});
return out;

const src = $('Build Approval Packet').all();
const out = [];
$input.all().forEach(function(item, i){
  const a = src[i] ? src[i].json : {};
  const d = (item.json && item.json.data) ? item.json.data : (item.json || {});
  function pick(obj, names){ for (var k = 0; k < names.length; k++) { const v = obj[names[k]]; if (v !== undefined && v !== null && v !== '') { return v; } } return undefined; }
  const decisionRaw = pick(d, ['Decision', 'decision']);
  const subjectRaw = pick(d, ['Subject', 'subject']);
  const bodyRaw = pick(d, ['Email Body', 'Email_Body', 'email_body', 'emailBody']);
  const approved = String(decisionRaw || '').trim().toLowerCase() === 'approve';
  const finalSubject = (subjectRaw !== undefined && subjectRaw !== '') ? subjectRaw : a.email_subject;
  const finalBody = (bodyRaw !== undefined && bodyRaw !== '') ? bodyRaw : a.email_body;
  const wasEdited = (finalSubject !== a.email_subject) || (finalBody !== a.email_body);
  out.push({ json: Object.assign({}, a, {
    approval_status: approved ? 'APPROVED' : 'REJECTED',
    approved_by: 'ALUMNI_RELATIONS_MANAGER',
    approval_decided_at: new Date().toISOString(),
    human_approved: approved,
    email_subject: finalSubject,
    email_body: finalBody,
    manager_edited: wasEdited
  }) });
});
return out;

const src = $('Resolve Approval Decision').all().filter(function(i){ return i.json.human_approved === true; });
const out = [];
$input.all().forEach(function(item, i){
  const a = src[i] ? src[i].json : {};
  const failed = !!(item.json && item.json.error);
  const editedNote = a.manager_edited ? ' Manager edited the copy before approving.' : '';
  out.push({ json: {
    log_id: 'LOG-' + $execution.id + '-' + (a.alumni_id || i),
    timestamp: new Date().toISOString(),
    alumni_id: a.alumni_id,
    event_id: a.event_id,
    action: failed ? 'SEND_FAILED' : 'INVITATION_SENT',
    relevance_score: a.relevance_score,
    relevance_band: a.relevance_band,
    personalization_confidence: a.personalization_confidence,
    personalization_angle: a.personalization_angle,
    message_status: failed ? 'SEND_FAILED_AFTER_RETRIES' : 'SENT',
    approval_status: 'APPROVED',
    risk_flags: (a.risk_flags || []).join('; '),
